def count_multiples_in_range(values, l, r):
    """Count how many values in the range [l, r] are multiples of a given value."""
    count = 0
    for i in range(l, r + 1):
        if values[i] % values[l] == 0:
            count += 1
    return count

n = int(input())
values = list(map(int, input().split()))
t = int(input())

# Preprocess: for each strength value, store the indices where it appears
from collections import defaultdict
strength_indices = defaultdict(list)
for idx, val in enumerate(values):
    strength_indices[val].append(idx)

for _ in range(t):
    l, r = map(int, input().split())
    total_ants = r - l + 1
    ants_eaten = 0

    # For each ant in the range [l, r]
    for i in range(l, r + 1):
        strength = values[i - 1]  # values is 0-indexed

        # Count how many ants j in [l, r] have values[j] % strength == 0
        count = 0
        for j in range(l, r + 1):
            if values[j - 1] % strength == 0:
                count += 1

        if count != total_ants:
            ants_eaten += 1

    print(ants_eaten)
