def longest_path(graph, start, visited, path):
    if len(path) > max_len[0]:
        max_len[0] = len(path)

    for neighbor in graph[start]:
        if not visited[neighbor]:
            visited[neighbor] = True
            path.append(neighbor)
            longest_path(graph, neighbor, visited, path)
            path.pop()
            visited[neighbor] = False

n = int(input())
while n != 0:
    graph = {}
    for _ in range(n):
        a, b = map(int, input().split())
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append(b)
        graph[b].append(a)

    max_len = [0]
    visited = {node: False for node in graph}

    for start in graph:
        visited[start] = True
        path = [start]
        longest_path(graph, start, visited, path)
        visited[start] = False

    print(max_len[0])
    n = int(input())
