    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    count = 0

    for i in range(n):
        product = 1
        sum_val = 0

        for j in range(i, n):
            product *= a[j]
            sum_val += a[j]

            if product > k * sum_val:
                break

            if product == k * sum_val:
                count += 1

    print(count)

solve()
