import sys

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m1 = int(data[1])
    m2 = int(data[2])

    # Read Mocha's edges
    mocha_edges = []
    idx = 3
    for _ in range(m1):
        u = int(data[idx])
        v = int(data[idx+1])
        mocha_edges.append((u, v))
        idx += 2

    # Read Diana's edges
    diana_edges = []
    for _ in range(m2):
        u = int(data[idx])
        v = int(data[idx+1])
        diana_edges.append((u, v))
        idx += 2

    # Find components in Mocha's forest
    parent_mocha = list(range(n + 1))
    rank_mocha = [1] * (n + 1)
    for u, v in mocha_edges:
        union(parent_mocha, rank_mocha, u, v)

    # Find components in Diana's forest
    parent_diana = list(range(n + 1))
    rank_diana = [1] * (n + 1)
    for u, v in diana_edges:
        union(parent_diana, rank_diana, u, v)

    # Find all pairs of nodes that can be connected
    result = []
    for u in range(1, n + 1):
        for v in range(u + 1, n + 1):
            if find(parent_mocha, u) != find(parent_mocha, v) and find(parent_diana, u) != find(parent_diana, v):
                result.append((u, v))

    # Output the result
    print(len(result))
    for u, v in result:
        print(u, v)

if __name__ == "__main__":
    solve()
"}

