def solve():
    n = int(input())
    # Track final value at each position
    final = {}
    for _ in range(n):
        a, b = map(int, input().split())
        # Swap values at positions a and b
        final[a], final[b] = final.get(b, b), final.get(a, a)

    # Now count inversions in the final sequence
    # We need to count pairs (i, j) where i < j and final[i] > final[j]

    # Get all values and compress coordinates
    values = list(final.values())
    values.sort()
    mapping = {v: i+1 for i, v in enumerate(values)}

    # Use Fenwick Tree to count inversions
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, i, delta):
            while i <= self.n:
                self.tree[i] += delta
                i += i & -i

        def query(self, i):
            res = 0
            while i > 0:
                res += self.tree[i]
                i -= i & -i
            return res

    ft = FenwickTree(len(values))
    inversions = 0

    # Traverse from right to left
    for i in range(len(values) - 1, -1, -1):
        val = values[i]
        inversions += ft.query(mapping[val])
        ft.update(mapping[val], 1)

    print(inversions)

solve()
