def find_cycle(graph, start):
    visited = set()
    path = []

    def dfs(node):
        if node in visited:
            return False
        if node in path:
            # We've found a cycle
            idx = path.index(node)
            cycle = path[idx:]
            return cycle
        visited.add(node)
        path.append(node)
        for neighbor in graph[node]:
            cycle = dfs(neighbor)
            if cycle:
                return cycle
        path.pop()
        return False

    cycle = dfs(start)
    if cycle:
        return cycle
    return None


def solve():
    N, M = map(int, input().split())
    graph = [[] for _ in range(N + 1)]

    for _ in range(M):
        A, B = map(int, input().split())
        graph[A].append(B)

    for start in range(1, N + 1):
        cycle = find_cycle(graph, start)
        if cycle:
            print(len(cycle))
            for v in cycle:
                print(v)
            return

    print(-1)

solve()

