def solve():
    T = int(input())
    for _ in range(T):
        n, k = map(int, input().split())
        oranges = []
        for _ in range(n):
            cost, weight = map(int, input().split())
            oranges.append((cost, weight))

        # DP array: dp[j] = max weight achievable with cost j
        dp = [0] * (k + 1)

        for cost, weight in oranges:
            # Update from right to left to avoid overwriting
            for j in range(k, cost - 1, -1):
                dp[j] = max(dp[j], dp[j - cost] + weight)

        print(dp[k])

