    # Precompute prefix sums for sign-variable sum
    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        if i % 2 == 1:
            # Odd position: +a_i
            prefix[i] = prefix[i - 1] + (1 if s[i - 1] == '+' else -1)
        else:
            # Even position: -a_i
            prefix[i] = prefix[i - 1] - (1 if s[i - 1] == '+' else -1)

    # Process queries
    print(q)
    for _ in range(q):
        l, r = map(int, input().split())
        # Compute sign-variable sum for [l, r]
        if l % 2 == 1:
            total = prefix[r] - prefix[l - 1]
        else:
            total = prefix[r] - prefix[l - 1]

        if total == 0:
            print(0)
        elif abs(total) == 1:
            print(1)
            # Find any rod with charge matching the needed change
            for i in range(l, r + 1):
                if i % 2 == 1:
                    if (total == 1 and s[i - 1] == '+') or (total == -1 and s[i - 1] == '-'):
                        print(i)
                        break
        else:  # abs(total) == 2
            print(2)
            # Find one rod with charge +1 at odd position and one with charge -1 at even position
            odd_pos = -1
