import sys

def count_factor_occurrences(s):
    """Count occurrences of the factor '01' in a binary string."""
    count = 0
    for i in range(len(s) - 1):
        if s[i] == '0' and s[i+1] == '1':
            count += 1
    return count

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    T = int(data[0])
    results = []

    for i in range(1, T + 1):
        s = data[i]
        results.append(str(count_factor_occurrences(s)))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    main()
"}

