    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # Find max1, max2, min1, min2
        max1 = max2 = -1
        min1 = min2 = float('inf')

        for num in a:
            if num > max1:
                max2 = max1
                max1 = num
            elif num > max2:
                max2 = num

            if num < min1:
                min2 = min1
                min1 = num
            elif num < min2:
                min2 = num

        # Calculate all possible products
        candidates = [
            max1 * min1,
            max2 * min1,
            max1 * min2,
            max2 * min2
        ]

        print(max(candidates))

