    k = int(input())
    n = input().strip()

    # Try to find the smallest number of digits to leave
    for length in range(1, k + 1):
        # Check all combinations of length digits
        for i in range(len(n) - length + 1):
            # Get the substring of length digits
            candidate = n[i:i+length]
            # Convert to integer
            num = int(candidate)
            # Check if it's not prime
            if not is_prime(num):
                print(length)
                print(candidate)
                break
        else:
            continue
        break
