def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

# Read input
t = int(input())
for _ in range(t):
    k = int(input())
    n = input().strip()

    # Try to find the smallest number of digits to leave
    for length in range(1, k + 1):
        # Check all combinations of length digits
        for indices in itertools.combinations(range(len(n)), length):
            # Get the digits at these indices
            candidate = ''.join(n[i] for i in indices)
            # Convert to integer
            num = int(candidate)
            # Check if it's not prime
            if not is_prime(num):
                print(length)
                print(candidate)
                break
        else:
            continue
        break
