def is_subsequence(subseq, arr):
    it = iter(arr)
    return all(c in it for c in subseq)


def solve():
    n, m, q = map(int, input().split())
    p = list(map(int, input().split()))
    a = list(map(int, input().split()))

    # Generate all cyclic shifts of p
    cyclic_shifts = []
    for i in range(n):
        cyclic_shifts.append(p[i:] + p[:i])

    output = []
    for _ in range(q):
        l, r = map(int, input().split())
        subsegment = a[l-1:r]

        found = False
        for shift in cyclic_shifts:
            # Check if shift is a subsequence of subsegment
            it = iter(subsegment)
            match = True
            for num in shift:
                found = False
                while True:
                    try:
                        if next(it) == num:
                            found = True
                            break
                    except StopIteration:
                        break
                if not found:
                    match = False
                    break
            if match:
                found = True
                break

        output.append('1' if found else '0')

    print(''.join(output))

solve()
