        n = int(input())
        if n == 0:
            break

        names = [input().strip() for _ in range(n)]

        # Precompute overlaps: overlap[i][j] = length of longest suffix of names[i] that matches prefix of names[j]
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                max_len = 0
                for k in range(min(len(names[i]), len(names[j]))):
                    if names[i][-1 - k] == names[j][k]:
                        max_len += 1
                    else:
                        break
                overlap[i][j] = max_len

        # DP: dp[mask][i] = minimum length of superstring for cities in mask ending with city i
        dp = [[float('inf')] * n for _ in range(1 << n)]

        for i in range(n):
            dp[1 << i][i] = len(names[i])

        for mask in range(1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue
                for j in range(n):
                    if mask & (1 << j):
                        continue
                    # dp[mask | (1 << j)][j] = min(dp[mask | (1 << j)][j], dp[mask][i] + len(names[j]) - overlap[i][j])
                    dp[mask | (1 << j)][j] = min(dp[mask | (1 << j)][j], dp[mask][i] + len(names[j]) - overlap[i][j])

        print(min(dp[(1 << n) - 1]))

