    banned.add((x, y))

# Check if we can place 3 chips: 1 on top, 1 on bottom, 1 on left/right
# We need to check if we can place 1 chip on top, 1 on bottom, and 1 on left or right
# without collision

def can_place_top():
    for col in range(1, n + 1):
        if col != 1 and col != n:  # not corner
            if (1, col) not in banned:
                return True, (1, col)
    return False, None

def can_place_bottom():
    for col in range(1, n + 1):
        if col != 1 and col != n:  # not corner
            if (n, col) not in banned:
                return True, (n, col)
    return False, None

def can_place_left():
    for row in range(1, n + 1):
        if row != 1 and row != n:  # not corner
            if (row, 1) not in banned:
                return True, (row, 1)
    return False, None

def can_place_right():
    for row in range(1, n + 1):
        if row != 1 and row != n:  # not corner
            if (row, n) not in banned:
                return True, (row, n)
    return False, None

# Try to place 3 chips: 1 on top, 1 on bottom, 1 on left/right
# We need to check if placing 1 chip on left or right is possible without collision
# with the top/bottom chips

def can_place_3():
    top_ok, top_pos = can_place_top()
    bottom_ok, bottom_pos = can_place_bottom()

    if top_ok and bottom_ok:
        # Check if we can place 1 chip on left or right without collision
        # with top and bottom

        # Check left
        left_ok, left_pos = can_place_left()
        if left_ok:
            # Check if top and left collide
            top_row, top_col = top_pos
            left_row, left_col = left_pos
            if top_row != left_row and top_col != left_col:
                # Check if bottom and left collide
                bottom_row, bottom_col = bottom_pos
                if bottom_row != left_row and bottom_col != left_col:
                    return True

        # Check right
        right_ok, right_pos = can_place_right()
        if right_ok:
            # Check if top and right collide
            top_row, top_col = top_pos
            right_row, right_col = right_pos
            if top_row != right_row and top_col != right_col:
                # Check if bottom and right collide
                bottom_row, bottom_col = bottom_pos
                if bottom_row != right_row and bottom_col != right_col:
                    return True

    return False

# Try to place 2 chips on the same edge (top or bottom)
# We need to check if we can place 2 chips on the same edge without collision

def can_place_2_same_edge():
    # Check top
    top_ok, top_pos1 = can_place_top()
    if top_ok:
        top_ok2, top_pos2 = can_place_top()
        if top_ok2 and top_pos1 != top_pos2:
            return True

    # Check bottom
    bottom_ok, bottom_pos1 = can_place_bottom()
    if bottom_ok:
        bottom_ok2, bottom_pos2 = can_place_bottom()
        if bottom_ok2 and bottom_pos1 != bottom_pos2:
            return True

    return False

# Try to place 2 chips on opposite edges (left and right)
# We need to check if we can place 2 chips on opposite edges without collision

def can_place_2_opposite_edges():
    # Check left and right
    left_ok, left_pos = can_place_left()
    if left_ok:
        right_ok, right_pos = can_place_right()
        if right_ok and left_pos != right_pos:
            return True

    return False

# Try to place 1 chip
# We need to check if we can place 1 chip anywhere on the border

def can_place_1():
    top_ok, _ = can_place_top()
    bottom_ok, _ = can_place_bottom()
    left_ok, _ = can_place_left()
    right_ok, _ = can_place_right()
    return top_ok or bottom_ok or left_ok or right_ok

