import sys
import math
from collections import defaultdict

def modinv(a, m):
    """Modular multiplicative inverse using Fermat's little theorem"""
    return pow(a, m - 2, m)

def comb(n, k, mod):
    """Compute combination C(n, k) modulo mod"""
    if n < k or k < 0:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n - k:
        k = n - k
    # Precompute factorials and inverse factorials
    fact = [1] * (n + 1)
    inv_fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % mod
    inv_fact[n] = modinv(fact[n], mod)
    for i in range(n - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % mod
    return fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod

MOD = 1000000007

def solve():
    q = int(sys.stdin.readline())
    for _ in range(q):
        n, f = map(int, sys.stdin.readline().split())
        if n < f:
            print(0)
            continue
        # Total ways to distribute n sweets to f friends with each getting at least 1
        total = comb(n - 1, f - 1, MOD)

        # Use inclusion-exclusion to count distributions where GCD > 1
        # We need to count distributions where GCD is divisible by some integer > 1
        # This is a classic inclusion-exclusion problem

        # Count distributions where GCD is divisible by d
        def count_divisible_by_d(d):
            if n % d != 0:
                return 0
            k = n // d
            if k < f:
                return 0
            return comb(k - 1, f - 1, MOD)

        # Inclusion-exclusion: sum over subsets of primes
        # We need to count all subsets of {2, 3, 5, 7, 11, ...} that divide n
        # This is complex, let me think differently

        # Instead, we can use Möbius function
        # The number of distributions where GCD = 1 is:
        # sum_{d|n} μ(d) * C(n/d - 1, f-1)

        # Find all divisors of n
        divisors = set()
        for i in range(1, int(math.isqrt(n)) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)

        answer = 0
        for d in divisors:
            if d == 1:
                continue
            # Count distributions where GCD is divisible by d
            k = n // d
            if k >= f:
                answer = (answer + comb(k - 1, f - 1, MOD)) % MOD

        # Answer = total - answer
        answer = (total - answer) % MOD
        print(answer)

if __name__ == "__main__":
    solve()
